ZZ_Probe_Allocator :: struct {
	base: mem.Allocator,
}

zz_probe_poison: u8 = 0xAA

zz_probe_allocator_proc :: proc(
	allocator_data: rawptr,
	mode: mem.Allocator_Mode,
	size, alignment: int,
	old_memory: rawptr,
	old_size: int,
	loc := #caller_location,
) -> ([]byte, mem.Allocator_Error) {
	wrapper := (^ZZ_Probe_Allocator)(allocator_data)
	if mode == .Free || mode == .Resize || mode == .Free_All {
		if old_memory != nil && old_size > 0 {
			mem.set(old_memory, int(zz_probe_poison), old_size)
		}
	}
	return wrapper.base.procedure(wrapper.base.data, mode, size, alignment, old_memory, old_size, loc)
}

